const t = $json;
const uid = String(t.user_id || '');
const chat = String(t.chat_id || '');
const name = String(t.user_name || '');
const text = String(t.text || '');
const key = text.toLowerCase().trim().slice(0, 200);
const esc = (s) => String(s == null ? '' : s).split('$x$').join('');
const sql = `select fn_conv_remember($x$${esc(uid)}$x$,$x$${esc(chat)}$x$,$x$${esc(name)}$x$,'in',null,null,$x$${esc(text)}$x$,null);\n`
  + `select fn_cache_get($x$${esc(key)}$x$) as cached,`
  + ` (select coalesce(jsonb_agg(jsonb_build_object('d',direction,'a',agent,'c',content) order by created_at desc),'[]'::jsonb) from fn_conv_recent($x$${esc(uid)}$x$,6)) as context,`
  + ` (select to_jsonb(p) from fn_conv_user_profile($x$${esc(uid)}$x$) p) as profile,`
  + ` fn_dashboard_snapshot() as dashboard;`;
return [{ json: { sql, cache_key: key } }];

let intent = 'singa';
try { const o = JSON.parse($json.choices[0].message.content); if (o && o.intent) intent = String(o.intent); } catch (e) {}
if (!['singa','operateur','analyste','ecriture'].includes(intent)) intent = 'singa';
const mem = $('Mémoire + cache + dashboard').item.json;
const ctx = JSON.stringify(mem.context || []);
const prof = JSON.stringify(mem.profile || {});
const dash = JSON.stringify(mem.dashboard || {});
const text = $('Contexte message').item.json.text;
const P = {
  singa: "Tu es Singa, la voix d'African College (marque culturelle, collectif d'artistes). Réponds en français, court, chaleureux, incarné. N'invente aucun chiffre. Ne promets aucune action sur la boutique : toute modification passe par une validation humaine.",
  operateur: "Tu es l'Opérateur d'African College. Réponds à partir des données fournies (Shopify en lecture, tableau de bord). Ne modifie rien. Si la donnée manque, dis-le plutôt que d'inventer. Français, concis, montants en EUR.",
  analyste: "Tu es l'Analyste d'African College. Explique la performance à partir du tableau de bord fourni (CA, marge %, panier, trafic, conversion, coût IA, erreurs, santé). 3-4 lignes + 1 action prioritaire. Chiffres fournis uniquement.",
  ecriture: "Tu es le garde-fou d'écriture d'African College. NE JAMAIS exécuter d'action boutique. Résume la demande en une proposition claire (objet, action, valeur, impact estimé) destinée à la validation humaine Telegram (Approuver/Refuser). Français."
};
let sys = P[intent] + '\n\nHistorique récent: ' + ctx + '\nProfil utilisateur: ' + prof;
if (intent === 'analyste' || intent === 'operateur') sys += '\nTableau de bord: ' + dash;
return [{ json: { intent, system: sys, user: text } }];

const resp = ($('Réponse IA').item.json.choices[0].message.content) || '';
const c = $('Contexte message').item.json;
const intent = $('Intent + persona').item.json.intent;
const key = $('Préparer SQL (in + lectures)').item.json.cache_key;
const esc = (s) => String(s == null ? '' : s).split('$x$').join('');
let sql = `select fn_conv_remember($x$${esc(c.user_id)}$x$,$x$${esc(c.chat_id)}$x$,$x$${esc(c.user_name)}$x$,'out',$x$${esc(intent)}$x$,$x$${esc(intent)}$x$,$x$${esc(resp)}$x$,null);`;
if (intent === 'singa') { sql += `\nselect fn_cache_put($x$${esc(key)}$x$,$x$${esc(c.text)}$x$,$x$${esc(resp)}$x$,24);`; }
return [{ json: { sql, response: resp } }];
